package api

import _ "embed"

// TeachingSchema is api/teaching.schema.json: the platform teaching spec
// (service-manager api/v2/teaching, closure of CommandRoutine, Dataset,
// DatasetPose and DatasetFrame), vendored by scripts/sync-teaching-schema.py
// (`make spec-sync`). It is the wire shape this service accepts, stores and
// emits; see docs/teaching.md.
//
//go:embed teaching.schema.json
var TeachingSchema []byte

// RoutineDialectSchema is api/routine-dialect.schema.json: the teaching-spec
// draft the resolver's CommandRoutine routes speak (motion_group references,
// motion_group_override, an optional start_joint_position), frozen from the
// draft it was built against. It describes and checks only those routes; what
// the dataset service stores follows TeachingSchema, the platform spec.
//
//go:embed routine-dialect.schema.json
var RoutineDialectSchema []byte

// TeachingOpenAPI is api/teaching-openapi.json: the dataset operations of the
// platform teaching API (paths, parameters, responses and the schemas they
// reach), vendored by the same script. The dataset service serves it verbatim
// as its contract, so a client written against the platform spec needs no
// adapter.
//
//go:embed teaching-openapi.json
var TeachingOpenAPI []byte
