            elif k.startswith("x-"):
                continue  # vendor extensions
            else:
                out[k] = rewrite(v)
        return out
    if isinstance(node, list):
        return [rewrite(v) for v in node]
    return node


def main():
    sm = sys.argv[1] if len(sys.argv) > 1 else os.path.expanduser("~/Arbeit/service-manager")
    api_dir = os.path.join(sm, "api")
    if not os.path.isdir(api_dir):
        sys.exit(f"service-manager api dir not found: {api_dir}")

    spec = bundle(api_dir)
    here = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    # The dataset API alone (its paths and the schemas they reach), served
    # verbatim by the dataset service as its contract.
    ds_paths = {p: v for p, v in spec["paths"].items() if "/datasets" in p}
    ds_roots = sorted(set(refs_in(ds_paths)))
    ds_keep = closure(spec["components"]["schemas"], ds_roots)
    ds_spec = {
        "openapi": spec["openapi"],
        "info": {"title": "Dataset Service (platform teaching API)", "version": spec["info"].get("version", ""),
                 "description": "The dataset operations of the platform teaching spec, vendored by "
                                "scripts/sync-teaching-schema.py and served verbatim. Extensions beyond the spec are "
                                "documented separately (docs/teaching.md)."},
        "paths": ds_paths,
        "components": {},
    }
    ds_spec["components"]["schemas"] = {n: spec["components"]["schemas"][n] for n in sorted(ds_keep)}
    # every other component kind: only what the dataset paths (and the kept
    # responses) reference — the platform spec's examples etc. stay out
    for section in ("parameters", "responses", "requestBodies", "headers", "examples", "securitySchemes"):
        used = {r.rsplit("/", 1)[1] for r in refs_any(ds_paths, section)}
        used |= {r.rsplit("/", 1)[1] for r in refs_any(ds_spec["components"].get("responses", {}), section)}
        kept = {n: v for n, v in spec["components"].get(section, {}).items() if n in used}
        if kept:
            ds_spec["components"][section] = kept
    if spec.get("security"):
        ds_spec["security"] = spec["security"]
        ds_spec["components"]["securitySchemes"] = spec["components"].get("securitySchemes", {})
    ds_spec["components"] = {k: v for k, v in ds_spec["components"].items() if v}
    with open(os.path.join(here, "api", "teaching-openapi.json"), "w") as f:
        json.dump(ds_spec, f, indent=2, sort_keys=True)
        f.write("\n")
    print(f"wrote api/teaching-openapi.json: {len(ds_paths)} dataset paths, {len(ds_keep)} schemas")
    schemas = spec["components"]["schemas"]
    keep = closure(schemas, ROOTS)
    defs = {name: rewrite(schemas[name]) for name in sorted(keep)}

    doc = {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$comment": (
            "VENDORED from service-manager api/v2/teaching — do not edit by hand; "
            "run scripts/sync-teaching-schema.py. Used by "
            "TestFixturesConformToTeachingSpec to detect drift between pkg/schema "
            "and the platform spec."
        ),
        "$defs": defs,
    }
    here = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    for dest in (
        os.path.join(here, "api", "teaching.schema.json"),
        os.path.join(here, "testdata", "teaching-schema.json"),
    ):
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, "w") as f:
            json.dump(doc, f, indent=2, sort_keys=True)
            f.write("\n")
    print(f"wrote {dest}: {len(defs)} schemas (closure of {', '.join(ROOTS)})")


if __name__ == "__main__":
    main()

