	c := jsonschema.NewCompiler()
	if err := c.AddResource("teaching.json", doc); err != nil {
		specError = fmt.Errorf("teaching schema: %w", err)
		return
	}
	for _, def := range []string{"DatasetPose", "DatasetFrame", "CommandRoutine"} {
		sch, err := c.Compile("teaching.json#/$defs/" + def)
		if err != nil {
			specError = fmt.Errorf("teaching schema %s: %w", def, err)
			return
		}
