	Position    [3]float64 `json:"position"`
	Orientation [3]float64 `json:"orientation"`
}

// UnmarshalJSON refuses a position or orientation that is not three numbers.
//
// Go fits a JSON array into [3]float64 by padding what is missing with zeros
// and dropping whatever comes after the third element, without complaint: a
// point written [1,2] reads as [1,2,0] and [1,2,3,4] as [1,2,3]. Both are a
// DIFFERENT PLACE than the one that was written, accepted in silence, and a
// taught point that quietly means somewhere else is the whole failure mode this
// service exists to prevent. Found by fuzzing the re-express endpoint.
