package main

// Every answer of the dataset service is a document of the platform teaching
// spec: the list is an array of Dataset, a dataset is a GetDatasetResponse, a
// transform answers a PoseList, an error is an Error. The vendored closure
// (testdata/teaching-schema.json, `make spec-sync`) is the judge — the same
// bytes the platform's own dataset service is generated from.

import (
	"encoding/json"
	"os"
	"testing"

	"github.com/santhosh-tekuri/jsonschema/v6"
)

func specDef(t *testing.T, def string) *jsonschema.Schema {
	t.Helper()
	f, err := os.Open("../../testdata/teaching-schema.json")
	if err != nil {
		t.Fatalf("vendored teaching schema missing (run `make spec-sync`): %v", err)
	}
	defer func() { _ = f.Close() }()
	doc, err := jsonschema.UnmarshalJSON(f)
	if err != nil {
		t.Fatal(err)
	}
	c := jsonschema.NewCompiler()
	if err := c.AddResource("teaching.json", doc); err != nil {
		t.Fatal(err)
	}
	s, err := c.Compile("teaching.json#/$defs/" + def)
	if err != nil {
		t.Fatalf("compile %s: %v", def, err)
	}
	return s
}

func mustValidate(t *testing.T, sch *jsonschema.Schema, body []byte, what string) {
	t.Helper()
	var v any
	if err := json.Unmarshal(body, &v); err != nil {
		t.Fatalf("%s: not JSON: %v", what, err)
	}
	if err := sch.Validate(v); err != nil {
		t.Errorf("%s does not conform to the spec:\n%v\n%s", what, err, body)
	}
}

func TestResponsesConformToTheTeachingSpec(t *testing.T) {
	st := newStack(t)
	dataset, getResp, poseList, errSch := specDef(t, "Dataset"), specDef(t, "GetDatasetResponse"), specDef(t, "PoseList"), specDef(t, "Error")

	code, body := st.do(t, "POST", "/v2/experimental/cells/cell/datasets", docJSON)
	if code != 201 {
		t.Fatalf("create: %d %s", code, body)
	}
	mustValidate(t, getResp, body, "createDataset response")
	_, body = st.do(t, "GET", "/v2/experimental/cells/cell/datasets/it-ds", "")
	mustValidate(t, getResp, body, "getDataset response")

	_, body = st.do(t, "GET", "/v2/experimental/cells/cell/datasets", "")
	var items []json.RawMessage
	if err := json.Unmarshal(body, &items); err != nil || len(items) != 1 {
		t.Fatalf("getDatasets must answer an array: %s", body)
	}
	mustValidate(t, dataset, items[0], "getDatasets item")

	_, body = st.do(t, "POST", "/v2/experimental/cells/cell/datasets/it-ds/frames/fix/resolve",
		`[{"position": [10,0,0], "orientation": [0,0,0]}, {"position": [0,0,0], "orientation": [0,0,1]}]`)
	mustValidate(t, poseList, body, "resolve response")
	_, body = st.do(t, "POST", "/v2/experimental/cells/cell/datasets/it-ds/frames/fix/localize", string(body))
	mustValidate(t, poseList, body, "localize response")

	for _, c := range []struct{ method, path, body string }{
