// teachingDefs loads the routine format (see teachingSchema) and rewrites its "#/$defs/X"
// references to OpenAPI component references.
func teachingDefs() (map[string]any, error) {
	b, err := teachingSchema()
	if err != nil {
		return nil, fmt.Errorf("teaching schema: %w", err)
	}
	var doc struct {
		Defs map[string]any `json:"$defs"`
	}
	if err := json.Unmarshal(b, &doc); err != nil {
		return nil, fmt.Errorf("teaching schema: %w", err)
	}
	rewritten := strings.ReplaceAll(string(mustJSON(doc.Defs)), "#/$defs/", "#/components/schemas/")
	var out map[string]any
	if err := json.Unmarshal([]byte(rewritten), &out); err != nil {
		return nil, err
	}
	// OpenAPI 3.1 is JSON Schema 2020-12, but generators choke on a few keys.
	for _, def := range out {
		if m, ok := def.(map[string]any); ok {
			delete(m, "$schema")
		}
	}
	return out, nil
}

// teachingSchema is the routine format the resolver's CommandRoutine routes
// speak (api.RoutineDialectSchema); the TEACHING_SCHEMA environment variable
// points at a file instead while iterating on it with `make spec`.
func teachingSchema() ([]byte, error) {
	if p := os.Getenv("TEACHING_SCHEMA"); p != "" {
		return os.ReadFile(p)
	}
	return api.RoutineDialectSchema, nil
}

func mustJSON(v any) []byte {
	b, err := json.Marshal(v)
	if err != nil {
		panic(err)
	}
	return b
}
