	openapi := readFile(t, "../../api/openapi.yaml")
	asyncapi := readFile(t, "../../api/asyncapi.yaml")
	bridge := readFile(t, "natsctl.go")
	handler := readFile(t, "server.go")

	for _, op := range sessionOps {
