--- torture
package main

// Torture the configured-motion-routine route against the assumptions it was
// built on. Each case writes the same motion twice — once as anchored poses,
// once as the document — from two independent templates, so the comparison is
// between two authors rather than the mapping checked against itself.
//
// The frames come from the mock's regression graph on purpose: a five-deep
// chain with a rotation at every hop, π-rotations about each axis and a
// diagonal (where the rotation-vector conversion is singular), a near-zero
// rotation, a frame whose parent is spelled "world", and a frame NAMED world
// that is not world. If a mapping loses a frame reference, these say so.

import (
	"encoding/json"
	"fmt"
	"strings"
	"testing"
	"time"
)

// configuredForm and documentForm describe one move, written both ways.
type moveCase struct {
	frame  string // the wire frame value, e.g. `"world"` or `{"type":"cell_frame","frame":"d5"}`
	tcp    string
	config string // raw JSON for kinematic_configuration, "free" = kinematic_configuration_mode: free, "" = absent
	path   string // path_definition_name
	extra  string // configured form: via / via_points
	pathIn string // document form: the same control points, inside path_type
}

func (c moveCase) configured() string {
	cfg := ""
	switch c.config {
	case "":
	case "free":
		cfg = `, "kinematic_configuration_mode": "free"`
	default:
		cfg = `, "kinematic_configuration": ` + c.config
	}
	return fmt.Sprintf(`{"motion_group": "0@mock", "steps": [{"type": "move",
	  "point": {"pose": {"position": [10, 20, 30], "orientation": [0, 0, 0]}, "frame": %s, "tcp": %q%s},
	  "path": {"path_definition_name": %q}%s}]}`, c.frame, c.tcp, cfg, c.path, c.extra)
}

func (c moveCase) document() string {
	cfg := ""
	switch c.config {
	case "":
	case "free": // the document's "deliberately none"
		cfg = `, "kinematic_configuration": null`
	default:
		cfg = `, "kinematic_configuration": ` + c.config
	}
	return fmt.Sprintf(`{"command_routine": "torture", "motion_group": "0@mock", "commands": [{"type": "motion_command",
	  "target": {"type": "inline", "pose": {"position": [10, 20, 30], "orientation": [0, 0, 0]}, "frame": %s, "tool": {"tcp": %q}%s},
	  "path_type": {"path_definition_name": %q%s}}]}`, c.frame, c.tcp, cfg, c.path, c.pathIn)
}

