--- bench
package resolver

import (
	"encoding/json"
	"os"
	"testing"

	"code.wabo.run/wandelos/service-manager/routine-resolver/pkg/schema"
)

func benchRoutine(b *testing.B, path string) *schema.CommandRoutine {
	raw, err := os.ReadFile(path)
	if err != nil {
		b.Fatal(err)
	}
	var r schema.CommandRoutine
	if err := json.Unmarshal(raw, &r); err != nil {
		b.Fatal(err)
	}
	return &r
}

// BenchmarkPlanRoutine: the in-process cost of planning a routine against the
// mock (frame math, validation, segmentation, verification) — the planner's
// own latency is excluded by the mock, so this isolates the resolver's share.
func BenchmarkPlanRoutine(b *testing.B) {
	m := newMockNova()
	defer m.close()
	res := &Resolver{Nova: m.client()}
	for _, path := range []string{"../../testdata/routines-v2/01-inline-tools-frames.json", "../../testdata/routines/09-frame-coverage.json"} {
		r := benchRoutine(b, path)
		b.Run(path[len("../../testdata/"):], func(b *testing.B) {
			for i := 0; i < b.N; i++ {
				if _, err := res.Plan("cell", r); err != nil {
					b.Fatal(err)
				}
			}
		})
	}
}

func BenchmarkRoutineDecodeEncode(b *testing.B) {
	for _, path := range []string{"../../testdata/routines/09-frame-coverage.json", "../../testdata/routines-v2/01-inline-tools-frames.json"} {
		raw, _ := os.ReadFile(path)
		b.Run(path[len("../../testdata/"):], func(b *testing.B) {
			for i := 0; i < b.N; i++ {
				var r schema.CommandRoutine
				if err := json.Unmarshal(raw, &r); err != nil {
					b.Fatal(err)
				}
				if _, err := json.Marshal(r); err != nil {
					b.Fatal(err)
				}
			}
		})
	}
}
