--- reap
package session

// Reclaiming abandoned sessions.
//
// A session owns its motion group exclusively. A client that creates one and
// then dies leaves that robot unavailable for good: every later create returns
// 409 pointing at a session nobody is driving. The deadman does not cover this
// — its lease arms on the FIRST heartbeat, so a client that never beats is
// exactly the one nothing was watching. Observed live: probe scripts that
// exited without deleting their session silently took vr4 out of service.
//
// The rule that makes reclaiming safe is that only sessions at STANDSTILL are
// eligible. Reclaiming can therefore free a stopped robot, but can never
// interrupt a moving one.

import (
	"testing"
	"time"

	"code.wabo.run/wandelos/service-manager/routine-resolver/internal/novamock"
)

// managerWith puts a session under a manager's control without going through
// Create (which would re-plan), so a test can drive lastSeen directly.
func managerWith(t *testing.T, s *Session, idle time.Duration) *Manager {
	t.Helper()
	m := &Manager{sessions: map[string]*Session{}, lastSeen: map[string]time.Time{},
		stop: make(chan struct{})}
	t.Cleanup(func() { m.stopOnce.Do(func() { close(m.stop) }) })
	m.sessions[s.ID] = s
